import { Audio } from 'expo-av';
  import { Platform } from 'react-native';

  // Embedded WAV sounds as base64 (generated for native iOS/Android)
  const SOUND_DATA: Record<string, string> = {
    move: 'data:audio/wav;base64,',
    capture: 'data:audio/wav;base64,',
    check: 'data:audio/wav;base64,',
    castle: 'data:audio/wav;base64,',
    gameStart: 'data:audio/wav;base64,',
    gameEnd: 'data:audio/wav;base64,',
  };

  class SoundManager {
    private sounds: Record<string, Audio.Sound | null> = {
      move: null,
      capture: null,
      check: null,
      castle: null,
      gameStart: null,
      gameEnd: null,
    };
    private isLoaded = false;
    private isMuted = false;

    async loadSounds() {
      if (this.isLoaded) return;
      try {
        await Audio.setAudioModeAsync({
          playsInSilentModeIOS: true,
          staysActiveInBackground: false,
          allowsRecordingIOS: false,
          shouldDuckAndroid: true,
        });
        if (Platform.OS !== 'web') {
          for (const [key, uri] of Object.entries(SOUND_DATA)) {
            try {
              const { sound } = await Audio.Sound.createAsync({ uri });
              this.sounds[key] = sound;
            } catch (e) {
              console.log('Error loading sound', key, e);
            }
          }
        }
        this.isLoaded = true;
      } catch (error) {
        console.log('Error in loadSounds:', error);
      }
    }

    setMuted(muted: boolean) {
      this.isMuted = muted;
    }

    getMuted() {
      return this.isMuted;
    }

    private async playNative(key: string) {
      const sound = this.sounds[key];
      if (!sound) return;
      try {
        await sound.setPositionAsync(0);
        await sound.playAsync();
      } catch (e) {
        console.log('Error playing sound', key, e);
      }
    }

    private playWebTone(frequency: number, duration: number) {
      if (typeof window !== 'undefined' && window.AudioContext) {
        try {
          const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
          const oscillator = audioContext.createOscillator();
          const gainNode = audioContext.createGain();
          oscillator.connect(gainNode);
          gainNode.connect(audioContext.destination);
          oscillator.frequency.value = frequency;
          oscillator.type = 'sine';
          gainNode.gain.setValueAtTime(0.1, audioContext.currentTime);
          gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + duration / 1000);
          oscillator.start(audioContext.currentTime);
          oscillator.stop(audioContext.currentTime + duration / 1000);
        } catch (e) {}
      }
    }

    async playMove() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') { this.playWebTone(440, 50); } else { await this.playNative('move'); }
    }

    async playCapture() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') { this.playWebTone(300, 100); } else { await this.playNative('capture'); }
    }

    async playCheck() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') { this.playWebTone(600, 150); } else { await this.playNative('check'); }
    }

    async playCastle() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') { this.playWebTone(350, 80); } else { await this.playNative('castle'); }
    }

    async playGameStart() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') {
        this.playWebTone(300, 100);
        setTimeout(() => this.playWebTone(400, 100), 100);
        setTimeout(() => this.playWebTone(500, 100), 200);
      } else { await this.playNative('gameStart'); }
    }

    async playGameEnd() {
      if (this.isMuted) return;
      if (Platform.OS === 'web') {
        this.playWebTone(500, 150);
        setTimeout(() => this.playWebTone(400, 150), 150);
        setTimeout(() => this.playWebTone(300, 200), 300);
      } else { await this.playNative('gameEnd'); }
    }

    async cleanup() {
      for (const sound of Object.values(this.sounds)) {
        if (sound) { try { await sound.unloadAsync(); } catch (e) {} }
      }
    }
  }

  export const soundManager = new SoundManager();
  